import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { StatusBadge } from '@/components/status-badge'
import { timelineEvents, type TimelineEvent } from '@/lib/mock-data'
import {
  FileText,
  MessageSquareText,
  Video,
  MapPin,
  Sparkles,
} from 'lucide-react'
import { cn } from '@/lib/utils'

const typeIcon: Record<TimelineEvent['type'], React.ElementType> = {
  evidence: FileText,
  witness: MessageSquareText,
  cctv: Video,
  location: MapPin,
  ai: Sparkles,
}

export function CaseTimeline() {
  return (
    <Card>
      <CardHeader className="border-b border-border/60 pb-3.5">
        <div>
          <CardTitle>Chronological Investigation Timeline</CardTitle>
          <p className="mt-0.5 font-mono text-[10.5px] text-muted-foreground">
            Interleaved verified facts and AI working-analysis hypotheses
          </p>
        </div>
        <div className="flex items-center gap-3 font-mono text-[10px] text-muted-foreground select-none">
          <span className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-success" /> Verified
          </span>
          <span className="flex items-center gap-1.5">
            <span className="size-2 rounded-full bg-primary" /> AI Working Layer
          </span>
        </div>
      </CardHeader>
      <CardContent className="pt-4">
        <ol className="relative space-y-1">
          {timelineEvents.map((ev, i) => {
            const Icon = typeIcon[ev.type]
            const isAI = ev.status === 'ai-extracted'
            return (
              <li key={ev.id} className="relative flex gap-3.5 pb-4.5 last:pb-0">
                {i < timelineEvents.length - 1 && (
                  <span className="absolute top-8 left-[14px] h-full w-px bg-border/80" />
                )}
                <div
                  className={cn(
                    'z-10 flex size-7.5 shrink-0 items-center justify-center rounded-full border shadow-xs transition-colors',
                    isAI
                      ? 'border-primary/45 bg-primary/15 text-primary'
                      : 'border-border/80 bg-secondary/80 text-muted-foreground',
                  )}
                >
                  <Icon className="size-3.5" />
                </div>

                <div
                  className={cn(
                    'flex-1 rounded-lg border p-3 transition-all duration-150 shadow-xs',
                    isAI
                      ? 'border-primary/30 bg-primary/[0.03] hover:border-primary/45'
                      : 'border-border/70 bg-card/50 hover:border-border hover:bg-card/70',
                  )}
                >
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-xs font-semibold text-foreground/90">
                        {ev.date} · {ev.time}
                      </span>
                      <StatusBadge status={ev.status} />
                    </div>
                    {ev.confidence !== undefined && (
                      <span className="inline-flex items-center gap-1 rounded bg-primary/10 px-1.5 py-0.5 font-mono text-[10px] text-primary border border-primary/25">
                        <span>Confidence:</span>
                        <span className="font-bold">{ev.confidence}%</span>
                      </span>
                    )}
                  </div>
                  <p className="mt-1.5 text-xs font-semibold text-foreground">
                    {ev.title}
                  </p>
                  <p className="mt-0.5 text-xs leading-relaxed text-muted-foreground">
                    {ev.description}
                  </p>
                  <div className="mt-2.5 flex items-center gap-1.5 border-t border-border/50 pt-2 font-mono text-[10px] text-muted-foreground">
                    <span className="text-muted-foreground/70 uppercase">Citing:</span>
                    <span className="text-foreground/80 font-medium">{ev.source}</span>
                  </div>
                </div>
              </li>
            )
          })}
        </ol>
      </CardContent>
    </Card>
  )
}

