'use client'

import { useEffect, useState } from 'react'
import { auditTrail } from '@/lib/mock-data'
import {
  Eye,
  ShieldCheck,
  Upload,
  Sparkles,
  Ban,
  Lock,
  Activity,
  Fingerprint,
  Database,
  CheckCircle2,
  ChevronRight,
  Hash,
  Radio,
} from 'lucide-react'
import { cn } from '@/lib/utils'

function actionIcon(action: string, result: string): React.ElementType {
  if (result === 'denied') return Ban
  if (action.startsWith('Viewed')) return Eye
  if (action.startsWith('Reviewed')) return ShieldCheck
  if (action.startsWith('Uploaded')) return Upload
  return Sparkles
}

function eventTone(action: string, result: string) {
  if (result === 'denied') return 'danger'
  if (action.startsWith('Reviewed')) return 'success'
  if (action.startsWith('Uploaded')) return 'primary'
  return 'neutral'
}

export function AuditTrail() {
  const [activeIndex, setActiveIndex] = useState(0)

  useEffect(() => {
    const timer = setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % Math.min(auditTrail.length, 5))
    }, 2600)

    return () => clearInterval(timer)
  }, [])

  const entries = auditTrail.slice(0, 5)

  return (
    <>
      <style jsx>{`
        @keyframes auditReveal {
          from {
            opacity: 0;
            transform: translateY(10px);
          }

          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes ledgerScan {
          0% {
            transform: translateX(-150%);
            opacity: 0;
          }

          20% {
            opacity: 0.8;
          }

          80% {
            opacity: 0.2;
          }

          100% {
            transform: translateX(450%);
            opacity: 0;
          }
        }

        @keyframes ledgerPulse {
          0%,
          100% {
            opacity: 0.35;
          }

          50% {
            opacity: 1;
          }
        }

        @keyframes chainGlow {
          0%,
          100% {
            opacity: 0.25;
          }

          50% {
            opacity: 0.8;
          }
        }

        @keyframes progress {
          from {
            width: 0%;
          }

          to {
            width: 100%;
          }
        }

        @keyframes nodePulse {
          0%,
          100% {
            transform: scale(0.9);
          }

          50% {
            transform: scale(1.12);
          }
        }

        .audit-reveal {
          animation: auditReveal 0.65s
            cubic-bezier(0.22, 1, 0.36, 1);
        }

        .ledger-scan {
          animation: ledgerScan 3.5s ease-in-out infinite;
        }

        .ledger-pulse {
          animation: ledgerPulse 2s ease-in-out infinite;
        }

        .chain-glow {
          animation: chainGlow 2.5s ease-in-out infinite;
        }

        .progress {
          animation: progress 1.2s
            cubic-bezier(0.22, 1, 0.36, 1);
        }

        .node-pulse {
          animation: nodePulse 2s ease-in-out infinite;
        }

        .audit-row {
          transition:
            transform 250ms ease,
            border-color 250ms ease,
            background-color 250ms ease,
            box-shadow 250ms ease;
        }

        .audit-row:hover {
          transform: translateX(3px);
          border-color: rgba(34, 211, 238, 0.2);
          background: rgba(34, 211, 238, 0.025);
        }

        @media (prefers-reduced-motion: reduce) {
          .audit-reveal,
          .ledger-scan,
          .ledger-pulse,
          .chain-glow,
          .progress,
          .node-pulse {
            animation: none;
          }
        }
      `}</style>

      <div className="audit-reveal relative overflow-hidden rounded-2xl border border-border/70 bg-card/45 shadow-lg backdrop-blur-xl">

        {/* =============================================== */}
        {/* FORENSIC GRID */}
        {/* =============================================== */}

        <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(rgba(100,180,210,0.012)_1px,transparent_1px),linear-gradient(90deg,rgba(100,180,210,0.012)_1px,transparent_1px)] bg-[size:20px_20px]" />

        <div className="pointer-events-none absolute -right-20 -top-20 size-52 rounded-full bg-primary/[0.035] blur-3xl" />


        {/* =============================================== */}
        {/* TOP SCANNER */}
        {/* =============================================== */}

        <div className="relative h-0.5 overflow-hidden bg-secondary/40">

          <div className="ledger-scan absolute h-full w-1/4 bg-primary/60 shadow-[0_0_12px_rgba(34,211,238,0.5)]" />

        </div>


        {/* =============================================== */}
        {/* HEADER */}
        {/* =============================================== */}

        <div className="relative border-b border-border/60 p-4">

          <div className="flex items-start justify-between gap-3">

            <div className="flex items-start gap-2.5">

              <div className="relative flex size-9 shrink-0 items-center justify-center rounded-lg border border-primary/25 bg-primary/[0.07] text-primary">

                <Fingerprint className="size-4" />

                <span className="ledger-pulse absolute -right-0.5 -top-0.5 size-1.5 rounded-full bg-success" />

              </div>


              <div>

                <div className="flex items-center gap-2">

                  <h2 className="text-sm font-bold tracking-tight text-foreground">
                    Immutable Audit Ledger
                  </h2>

                  <span className="hidden rounded border border-success/20 bg-success/10 px-1.5 py-0.5 font-mono text-[7px] font-bold text-success sm:inline-block">
                    WORM SECURED
                  </span>

                </div>

                <p className="mt-0.5 font-mono text-[8.5px] uppercase tracking-wider text-muted-foreground">
                  Append-only cryptographic audit stream
                </p>

              </div>

            </div>


            <div className="flex items-center gap-1.5 rounded border border-success/20 bg-success/[0.035] px-2 py-1 font-mono text-[7px] font-bold uppercase tracking-wider text-success">

              <Radio className="size-2.5" />

              LIVE

            </div>

          </div>


          {/* STATUS */}

          <div className="mt-4 grid grid-cols-3 gap-2">

            <LedgerStat
              icon={Database}
              value={`${entries.length}`}
              label="Events"
            />

            <LedgerStat
              icon={Hash}
              value="SHA-256"
              label="Integrity"
            />

            <LedgerStat
              icon={Lock}
              value="100%"
              label="Tamper Proof"
            />

          </div>

        </div>


        {/* =============================================== */}
        {/* CHAIN INTEGRITY */}
        {/* =============================================== */}

        <div className="relative mx-3.5 mt-3.5 rounded-xl border border-success/15 bg-success/[0.025] p-3">

          <div className="flex items-center justify-between">

            <div className="flex items-center gap-2">

              <ShieldCheck className="size-3.5 text-success" />

              <span className="font-mono text-[8px] font-bold uppercase tracking-[0.14em] text-muted-foreground">
                Cryptographic Chain
              </span>

            </div>

            <span className="font-mono text-[8px] font-bold text-success">
              VERIFIED
            </span>

          </div>


          {/* chain nodes */}

          <div className="relative mt-3 flex items-center">

            {entries.map((entry, index) => (

              <div
                key={entry.id}
                className="relative flex flex-1 items-center"
              >

                <div
                  className={cn(
                    'node-pulse relative z-10 flex size-5 items-center justify-center rounded-full border',
                    index === activeIndex
                      ? 'border-primary/50 bg-primary/15'
                      : 'border-success/30 bg-success/10',
                  )}
                  style={{
                    animationDelay: `${index * 0.25}s`,
                  }}
                >

                  <span
                    className={cn(
                      'size-1.5 rounded-full',
                      index === activeIndex
                        ? 'bg-primary shadow-[0_0_8px_rgba(34,211,238,0.7)]'
                        : 'bg-success',
                    )}
                  />

                </div>


                {index < entries.length - 1 && (

                  <div className="relative h-px flex-1 overflow-hidden bg-success/20">

                    <div className="chain-glow absolute h-full w-1/3 bg-success/60" />

                  </div>

                )}

              </div>

            ))}

          </div>


          <div className="mt-2 flex justify-between font-mono text-[6.5px] uppercase tracking-wider text-muted-foreground">

            <span>Origin</span>

            <span>Verified chain</span>

            <span>Latest</span>

          </div>

        </div>


        {/* =============================================== */}
        {/* EVENT STREAM */}
        {/* =============================================== */}

        <div className="relative p-3.5">

          <div className="mb-2 flex items-center justify-between">

            <span className="flex items-center gap-1.5 font-mono text-[8px] font-bold uppercase tracking-[0.14em] text-muted-foreground">

              <Activity className="size-3 text-primary" />

              Access Stream

            </span>

            <span className="font-mono text-[7px] uppercase tracking-wider text-muted-foreground">
              {entries.length} EVENTS
            </span>

          </div>


          <ul className="space-y-1.5">

            {entries.map((entry, index) => {

              const Icon = actionIcon(
                entry.action,
                entry.result,
              )

              const isDenied = entry.result === 'denied'

              const tone = eventTone(
                entry.action,
                entry.result,
              )

              const isActive = index === activeIndex


              return (

                <li
                  key={entry.id}
                  className={cn(
                    'audit-row relative flex items-center gap-2.5 overflow-hidden rounded-lg border px-2.5 py-2',
                    isActive
                      ? 'border-primary/25 bg-primary/[0.035]'
                      : 'border-border/50 bg-background/15',
                  )}
                >

                  {/* active scanner */}

                  {isActive && (
                    <span className="ledger-scan pointer-events-none absolute left-0 top-0 h-px w-1/3 bg-primary/60" />
                  )}


                  {/* timeline node */}

                  <div className="relative flex flex-col items-center">

                    <div
                      className={cn(
                        'flex size-7 shrink-0 items-center justify-center rounded-md border',
                        isDenied
                          ? 'border-danger/30 bg-danger/10 text-danger'
                          : tone === 'success'
                            ? 'border-success/20 bg-success/10 text-success'
                            : tone === 'primary'
                              ? 'border-primary/20 bg-primary/10 text-primary'
                              : 'border-border/60 bg-secondary/70 text-muted-foreground',
                      )}
                    >

                      <Icon className="size-3" />

                    </div>

                  </div>


                  {/* event details */}

                  <div className="min-w-0 flex-1">

                    <div className="flex items-center gap-2">

                      <p className="truncate text-[10px] font-semibold text-foreground">
                        {entry.action}
                      </p>

                      {isDenied && (

                        <span className="rounded border border-danger/20 bg-danger/10 px-1 py-0.5 font-mono text-[6px] font-bold text-danger">
                          DENIED
                        </span>

                      )}

                    </div>


                    <p className="truncate font-mono text-[8px] text-muted-foreground">

                      <span className="font-bold text-foreground/80">
                        {entry.actor}
                      </span>

                      <span className="mx-1 text-border">
                        ·
                      </span>

                      {entry.role}

                    </p>

                  </div>


                  {/* timestamp */}

                  <div className="flex shrink-0 items-center gap-1.5">

                    <span className="font-mono text-[8px] font-medium text-muted-foreground">
                      {entry.time}
                    </span>

                    <ChevronRight className="size-2.5 text-muted-foreground/40" />

                  </div>

                </li>

              )
            })}

          </ul>

        </div>


        {/* =============================================== */}
        {/* INTEGRITY FOOTER */}
        {/* =============================================== */}

        <div className="border-t border-border/50 bg-secondary/[0.15] px-3.5 py-2.5">

          <div className="flex items-center justify-between gap-2">

            <div className="flex min-w-0 items-center gap-1.5">

              <CheckCircle2 className="size-3 shrink-0 text-success" />

              <span className="truncate font-mono text-[7.5px] uppercase tracking-wider text-muted-foreground">
                Ledger integrity verified
              </span>

            </div>


            <div className="flex shrink-0 items-center gap-1.5">

              <span className="font-mono text-[7px] font-bold text-success">
                100%
              </span>

              <div className="h-1 w-10 overflow-hidden rounded-full bg-secondary">

                <div className="progress h-full w-full rounded-full bg-success" />

              </div>

            </div>

          </div>

        </div>

      </div>
    </>
  )
}


/* ===================================================== */
/* LEDGER STAT */
/* ===================================================== */

function LedgerStat({
  icon: Icon,
  value,
  label,
}: {
  icon: React.ElementType
  value: string
  label: string
}) {
  return (
    <div className="rounded-lg border border-border/50 bg-background/20 p-2">

      <div className="flex items-center gap-1.5">

        <Icon className="size-3 text-primary" />

        <span className="font-mono text-[7px] uppercase tracking-wider text-muted-foreground">
          {label}
        </span>

      </div>

      <p className="mt-1 font-mono text-[10px] font-bold text-foreground">
        {value}
      </p>

    </div>
  )
}